def find_good_set(n_vertices, edges, start, stop, end):
    graph = defaultdict(list)
    incoming_edges = defaultdict(int)

    for start_node, end_node in edges:
        graph[start_node].append(end_node)
        incoming_edges[end_node] += 1

    visited = set()
    ordering = []

    for node in range(1, n_vertices + 1):
        if node not in visited:
            start = node
            visited.add(node)
            ordering = topological_sort(start, node, visited, ordering)

    current = start

    for i in range(len(ordering) - 2):
        current = ordering.pop()
        if graph[current]:
            return False

    current = start

    for i in range(len(ordering) - stop):
        current = ordering.pop(stop)
        if graph[current]:
            return False

    return True

