import sys
import collections

def dijkstra(graph, start):
    distances = {vertex: float('inf') for vertex in graph}
    distances[start] = 0
    visited = set()
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_vertex = priority_queue.pop(0)

        if current_vertex in visited:
            continue

        visited.add(current_vertex)

        for neighbor, weight in graph[current_vertex].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                priority_queue.append((distance, neighbor))

    return distances

def find_set(graph, vertex, start_time, distance):
    time = start_time
    visited = {vertex}
    queue = collections.deque([vertex])

    while queue:
        current_vertex = queue.popleft()

        for neighbor, weight in graph[current_vertex].items():
            shortcut = distance[current_vertex] + weight

            if neighbor in graph and neighbor not in visited and shortcut < time:
                time = shortcut
                queue.append(neighbor)

    return time

def solve(n, m, edges):
    graph = collections.defaultdict(dict)

    for a, b in edges:
        graph[a][a] = 0
        graph[b][b] = 0
        graph[a][b] = 1
        graph[b][a] = 1

    for vertex in range(1, n + 1):
        shortest_time = dijkstra(graph, vertex)
        minimum_cost_time = min(shortest_time.values())
        time = 0

        for vertex in range(1, n + 1):
            if vertex in graph:
                current_cost = sum(graph[vertex][x] for x in graph[vertex].keys())
                current_cost_time = find_set(graph, vertex, time, current_cost)
                if current_cost_time >= minimum_cost_time and time < current_cost_time:
                    return time

        time = minimum_cost_time + 1

    return 0

n, m = map(int, input().split())
edges = [tuple(map(int, input().split())) for _ in range(m)]
