        minFeeTowers.sort(key=lambda s: (~s)[-1] * (-1 if distanceT towers[s] < dFee else 1))
        if len(minFeeTowers) < 2:
            dFee += 2
        else:
            dFee = min(dFee, dFeeTowers[1])
    return dFee

def countOrderedSet(arr, freq):
    diff = arr[-1] - arr[0]
    eff = sum(set.bit_count(i) for i in freq)
    return (diff - eff + 2) // 2 * diff - ((diff * diff - diff) - (eff * eff - eff) + eff * eff) // 2

