from collections import Counter
from math import sqrt

def expected_inversions(n, k):
    if n <= 4:
        return 0.5 * int(sqrt(k) + 1)
    else:
        r_binom = 0
        for a in range(1, 2*n-2):
            p = [a] + [a-1] * n - [i ** 2 % n for i in range(a)]
            if max(abs(i - j) % n for i, j in itertools.combinations(p, 2)) < n // 2:
                continue
            c = Counter()
            for i in p:
                c[(-i - 1) % n] += 1
            q = [c.keys()[-1] - 2]
            for j in range(2 * n - 3):
                q.append(
                    min(max(-q[-1], c[-j - 2]), max(-q[-1] - 1, 2 * n - 1 - c[-j - 1]) - 2)
                )
            q = sorted(q)
            r_binom += 1 - max(a, sum((-1 + 2 * q[-1] - i) for i in range(a, n))) / (a + n - 2 * a * (a - 1) // 4)

        return sum([(n - i - 1) * expected_inversions(i, k - r_binom) for i in range(n)])

