from math import gcd
from functools import lru_cache

def extended_gcd(a, b):
    """ Extended Euclidean Algorithm to find the coefficients x and y such that ax + by = gcd(a, b) """
    if b == 0:
        return a, 1, 0
    else:
        gcd, x1, y1 = extended_gcd(b, a % b)
        x = y1
        y = x1 - (a // b) * y1
        return gcd, x, y

@lru_cache None
def modular_inverse(a, mod):
    """ Modular multiplicative inverse """
    _, x, _ = extended_gcd(a, mod)
    return x % mod

def nCr(n, r):
    """ Calculate nCr using factorial """
    return (factorial[n] * modular_inverse(factorial[r] * factorial[n - r] % MOD, MOD)) % MOD

@lru_cache None
def factorial_mod(n, MOD=998244353):
    """ Calculate n! using modular arithmetic """
    if n <= 1:
        return 1
    return n * factorial(n-1) % MOD

