def dfs(vertex, time, tree, path, visit, target):
    visit.add(vertex)
    for neighbor in tree[vertex]:
        if neighbor not in visit:
            path[0] = neighbor
            dfs(neighbor, time + 1, tree, path, visit, target)
            if target:
                path[0] = vertex
                dfs(vertex, time + 1, tree, path, visit, target)
        if neighbor == target:
            path[0] = vertex
            return 
