def nondecr(prefix, numbers):
    n = len(prefix)
    dp = []
    for elem in numbers:
        i = elem % n
        dp.append(prefix[i] + 1 if prefix else 0)
        i = min(i+1, n-1)
        min_right = i
        for right in range(i+1,n+1):
            if prefix[right] < dp.pop():
                min_right = right
                dp.append(prefix[right] + 1 if prefix else 0)
                break
    i0 = dp.index(min(dp))
    idx = -1
    for i in range(i0+1):
        idx_ = (n-i-1) * dp[i]
        if idx == -1 or idx_ > idx:
            idx = (n-i-1) * dp[i]
    return idx // n + 1


