def cartesian_product(n1, n2, k):
    mod = 998244353
    adj = {i: set() for i in range(n1 * n2)}

    for _ in range(n1 - 1):
        v1, u1 = map(int, input().split())
        adj[v1 * n2 + u1].add(u1)

