        v2, u2 = map(int, input().split())
        if v1 != v2:
            adj[v1 * n2 + u1].add(u2)
            adj[v2 * n2 + u1].add(u1)

    dp = [0] * (k + 1)
    dp[0] = 1
    for i in range(1, k + 1):
        for v in range(n1 * n2):
            for u in adj[v]:
                dp[i] = (dp[i] + 1) % mod
        for u in adj[v]:
            if u == 0:
                continue
            for i2 in range(k + 1):
                dp[i2] = ((dp[i2] - dp[i2 - u]) % mod * dp[k - u]) % mod
            dp[k] = (dp[k] + dp[i] * 2) % mod

