    count_of_each_pattern = [0] * (1 << x_pattern_length)

    for number in arr:
        currentPattern = 0
        for i, bit in enumerate(bin(number)[2:].zfill(x_pattern_length)):
            if bit == '1':
                currentPattern |= (1 << (x_pattern_length - i - 1))

        # This operation is slow, violating the constant query-time constraint.
        count_of_each_pattern[currentPattern] += 1

        left = 0
        prev_count = 0
        total_pairs += (count_of_each_pattern[prev_count] - prev_count - 1) * (count_of_each_pattern[currentPattern] - prev_count - 1)

