def EuclideanDistance(x1, y1, x2, y2):
    return abs(x1 - x2) + abs(y1 - y2)

def max_cost(n, towers):
    max_cost_so_far = 0

    for i in range(n):
        for j in range(i + 1, n):
            cost = EuclideanDistance(towers[i][0], towers[i][1], towers[j][0], towers[j][1])
            if cost > max_cost_so_far:
                max_cost_so_far = cost

    return max_cost_so_far

def count_assignments(cn, towers, max_cost, dp):
    dp[1][1] = 1
    prev_cnt = {1: 1}
    for i in range(1, cn + 1):
        dp[i][0] = prev_cnt[i - 1]
        curr_cnt = [0] * cn
        for j in range(1, i + 1):
            for k in range(0, j):
                d = EuclideanDistance(towers[j - 1][0], towers[j - 1][1], towers[k - 1][0], towers[k - 1][1])
                if d <= max_cost:
                    dp[i][j] += dp[j - k][k] % 1000000007
                    curr_cnt[j] += curr_cnt[k] + 1
            for k in range(0, j):
                dp[i][j] += prev_cnt[j] * curr_cnt[k] % 1000000007
            for k in range(0, j):
                dp[i][j] %= 1000000007
        for j in range(0, n):
            if count_occurrences(dp[i][j], prev_cnt):
                dp[i][j] = 0
        for j in range(1, cn + 1):
            if j == i:
                prev_cnt[j] = 0
            else:
                prev_cnt[j] = curr_cnt[j] - prev_cnt[j - 1]
        prev_cnt[i] = 1

    return (dp[cn][cn] + 1000000007) % 1000000007

