def find_non_optimal_sum():
    n = int(input().strip())
    coins = list(map(int, input().strip().split()))
    sorted_coins = sorted(coins)

    def greedy_function(x):
        coin_count = 0
        for coin in sorted_coins:
            if coin <= x:
                x -= coin
                coin_count += 1
        return x, coin_count

    smallest_non_optimal_sum = float('inf')

    # Check if greedy algorithm works for any sum
    for change in range(1, 10**9 + 1):
        min_coins = greedy_function(change)[1]
        if min_coins >= 10:
            break

        # Check if there is any sum where greedy algorithm fails
        old_change = change
        while greedy_function(old_change)[1] >= 10:
            old_change += 1

        if old_change > change:
            smallest_non_optimal_sum = min(smallest_non_optimal_sum, change)

    return -1 if smallest_non_optimal_sum != float('inf') else smallest_non_optimal_sum

if __name__ == "__main__":
    print(find_non_optimal_sum())
